package br.com.helptech.agenda;
import android.app.*;import android.content.*;import android.media.*;import android.os.*;
public class AlarmReceiver extends android.content.BroadcastReceiver {
 static final String CHANNEL="helptech_sirene_v2";
 @Override public void onReceive(Context c,Intent i){String action=i.getAction();String id=i.getStringExtra("id");if(id==null)return;int notificationId=id.hashCode();NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);
  if("RECONHECER".equals(action)){nm.cancel(notificationId);return;}
  if("ADIAR".equals(action)){nm.cancel(notificationId);Intent next=new Intent(c,AlarmReceiver.class).setAction("ALARM_"+id).putExtra("id",id).putExtra("client",i.getStringExtra("client")).putExtra("service",i.getStringExtra("service")).putExtra("time",i.getStringExtra("time"));PendingIntent p=PendingIntent.getBroadcast(c,notificationId,next,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);long when=System.currentTimeMillis()+1800000L;if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);else am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,when,p);return;}
  if(Build.VERSION.SDK_INT>=26){NotificationChannel channel=new NotificationChannel(CHANNEL,"Sirene de serviços",NotificationManager.IMPORTANCE_HIGH);channel.setDescription("Alertas de serviços agendados");channel.enableVibration(true);channel.setSound(android.provider.Settings.System.DEFAULT_ALARM_ALERT_URI,new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).build());nm.createNotificationChannel(channel);}
  Intent ack=new Intent(c,AlarmReceiver.class).setAction("RECONHECER").putExtra("id",id);Intent snooze=new Intent(c,AlarmReceiver.class).setAction("ADIAR").putExtra("id",id).putExtra("client",i.getStringExtra("client")).putExtra("service",i.getStringExtra("service")).putExtra("time",i.getStringExtra("time"));
  PendingIntent pAck=PendingIntent.getBroadcast(c,notificationId+1,ack,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE),pSnooze=PendingIntent.getBroadcast(c,notificationId+2,snooze,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
  Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(c,CHANNEL):new Notification.Builder(c);b.setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle("HELP-TECH • Serviço agendado").setContentText(i.getStringExtra("client")+" • "+i.getStringExtra("time")).setStyle(new Notification.BigTextStyle().bigText(i.getStringExtra("client")+" • "+i.getStringExtra("service")+" • "+i.getStringExtra("time"))).setAutoCancel(false).setOngoing(true).setPriority(Notification.PRIORITY_MAX).addAction(android.R.drawable.ic_menu_close_clear_cancel,"Reconhecer",pAck).addAction(android.R.drawable.ic_menu_recent_history,"Prorrogar 30 minutos",pSnooze);
  nm.notify(notificationId,b.build());
 }
}
